SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">KONTROLLÜ DENEY TASARIMI: Zn(k) + 2HCl(suda) -&gt; ZnCl2(suda) + H2(g)</text>\n  <rect x="20" y="48" width="210" height="192" rx="8" fill="#dbeafe" stroke="#2563eb" stroke-width="1.8"/>\n  <text x="125" y="72" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">1. Kap (Referans Deney)</text>\n  <text x="32" y="98" font-size="10.5" fill="#334155">• Madde: 5 g Parça (Şerit) Zn</text>\n  <text x="32" y="120" font-size="10.5" fill="#334155">• Asit: 100 mL, 1 M HCl</text>\n  <text x="32" y="142" font-size="10.5" fill="#334155">• Sıcaklık: 25 °C</text>\n  <rect x="32" y="162" width="186" height="62" rx="6" fill="#ffffff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="125" y="182" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#1d4ed8">Ölçülen Süre: t1 = 120 saniye</text>\n  <text x="125" y="200" text-anchor="middle" font-size="10" fill="#475569">Toplanan H2 gazı: V litre</text>\n  <text x="125" y="214" text-anchor="middle" font-size="10" fill="#475569">Başlangıç hızı: r1</text>\n\n  <rect x="245" y="48" width="210" height="192" rx="8" fill="#dcfce7" stroke="#16a34a" stroke-width="1.8"/>\n  <text x="350" y="72" text-anchor="middle" font-size="12" font-weight="bold" fill="#15803d">2. Kap (Temas Yüzeyi Etkisi)</text>\n  <text x="257" y="98" font-size="10.5" font-weight="bold" fill="#166534">• Madde: 5 g TOZ Zn (Farklı!)</text>\n  <text x="257" y="120" font-size="10.5" fill="#334155">• Asit: 100 mL, 1 M HCl (Sabit)</text>\n  <text x="257" y="142" font-size="10.5" fill="#334155">• Sıcaklık: 25 °C (Sabit)</text>\n  <rect x="257" y="162" width="186" height="62" rx="6" fill="#ffffff" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="350" y="182" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#15803d">Ölçülen Süre: t2 = 45 saniye</text>\n  <text x="350" y="200" text-anchor="middle" font-size="10" fill="#475569">Toplanan H2 gazı: V litre (Aynı)</text>\n  <text x="350" y="214" text-anchor="middle" font-size="10" font-weight="bold" fill="#166534">Sonuç: r2 &gt; r1 (Daha hızlı!)</text>\n\n  <rect x="470" y="48" width="210" height="192" rx="8" fill="#fef3c7" stroke="#d97706" stroke-width="1.8"/>\n  <text x="575" y="72" text-anchor="middle" font-size="12" font-weight="bold" fill="#92400e">3. Kap (Sıcaklık Etkisi)</text>\n  <text x="482" y="98" font-size="10.5" fill="#334155">• Madde: 5 g Parça Zn (Sabit)</text>\n  <text x="482" y="120" font-size="10.5" fill="#334155">• Asit: 100 mL, 1 M HCl (Sabit)</text>\n  <text x="482" y="142" font-size="10.5" font-weight="bold" fill="#b45309">• Sıcaklık: 50 °C (Farklı!)</text>\n  <rect x="482" y="162" width="186" height="62" rx="6" fill="#ffffff" stroke="#f59e0b" stroke-width="1.5"/>\n  <text x="575" y="182" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#b45309">Ölçülen Süre: t3 = 50 saniye</text>\n  <text x="575" y="200" text-anchor="middle" font-size="10" fill="#475569">Toplanan H2 gazı: V litre (Aynı)</text>\n  <text x="575" y="214" text-anchor="middle" font-size="10" font-weight="bold" fill="#92400e">Sonuç: r3 &gt; r1 (Daha hızlı!)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">DENEYSEL VERİ GRAFİKLERİ VE HIZ DEĞİŞKENLERİNİN ETKİ TABLOSU</text>\n  <rect x="20" y="48" width="320" height="192" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="180" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e40af">H2 Gaz Hacmi - Zaman Grafiği Yorumu</text>\n  <line x1="55" y1="210" x2="310" y2="210" stroke="#334155" stroke-width="2"/>\n  <line x1="55" y1="210" x2="55" y2="85" stroke="#334155" stroke-width="2"/>\n  <text x="300" y="228" font-size="10" font-weight="bold" fill="#334155">Zaman (s)</text>\n  <text x="35" y="82" font-size="10" font-weight="bold" fill="#334155">V(H2)</text>\n  <path d="M 55 210 Q 95 110 140 110 L 300 110" fill="none" stroke="#16a34a" stroke-width="2.5"/>\n  <path d="M 55 210 Q 140 110 230 110 L 300 110" fill="none" stroke="#dc2626" stroke-width="2.2" stroke-dasharray="5,3"/>\n  <text x="115" y="102" font-size="10" font-weight="bold" fill="#15803d">I: Toz Zn / Sıcak / Katalizörlü</text>\n  <text x="185" y="145" font-size="10" font-weight="bold" fill="#b91c1c">II: Parça Zn / Soğuk</text>\n  <line x1="140" y1="110" x2="140" y2="210" stroke="#16a34a" stroke-width="1" stroke-dasharray="3,3"/>\n  <line x1="230" y1="110" x2="230" y2="210" stroke="#dc2626" stroke-width="1" stroke-dasharray="3,3"/>\n  <text x="140" y="224" text-anchor="middle" font-size="9.5" fill="#15803d">t1</text>\n  <text x="230" y="224" text-anchor="middle" font-size="9.5" fill="#b91c1c">t2</text>\n\n  <rect x="360" y="48" width="320" height="192" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="520" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#92400e">Faktörlerin Eşik Enerjisi (Ea) ve Hıza Etkisi</text>\n  <rect x="374" y="84" width="292" height="142" rx="6" fill="#ffffff" stroke="#f59e0b" stroke-width="1.5"/>\n  <text x="384" y="104" font-size="10.5" font-weight="bold" fill="#b45309">• Derişim Artışı:</text>\n  <text x="478" y="104" font-size="10" fill="#334155">Ea değişmez, etkin çarpışma artar.</text>\n  <text x="384" y="128" font-size="10.5" font-weight="bold" fill="#b45309">• Sıcaklık Artışı:</text>\n  <text x="482" y="128" font-size="10" fill="#334155">Ea değişmez, KE ve hız artar.</text>\n  <text x="384" y="152" font-size="10.5" font-weight="bold" fill="#15803d">• Katalizör:</text>\n  <text x="455" y="152" font-size="10" font-weight="bold" fill="#166534">Ea DÜŞER, mekanizma değişir, hız artar.</text>\n  <text x="384" y="176" font-size="10.5" font-weight="bold" fill="#15803d">• Temas Yüzeyi:</text>\n  <text x="475" y="176" font-size="10" fill="#334155">Ea değişmez, çarpışma yüzeyi ve hız artar.</text>\n  <text x="384" y="202" font-size="10" font-weight="bold" fill="#1e40af">* Hız sabiti (k): Sıcaklık, Katalizör, Temas Yüzeyi</text>\n  <text x="392" y="216" font-size="10" font-weight="bold" fill="#1e40af">ve Madde Cinsi ile değişir (Derişimle değişmez!).</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">LABORATUVARDA TEPKİME HIZINI DENEYSEL İZLEME YÖNTEMLERİ</text>\n  <rect x="20" y="48" width="210" height="192" rx="8" fill="#f0fdf4" stroke="#16a34a" stroke-width="1.8"/>\n  <text x="125" y="72" text-anchor="middle" font-size="12" font-weight="bold" fill="#15803d">1. Basınç / Hacim ve Renk</text>\n  <text x="30" y="96" font-size="10.5" font-weight="bold" fill="#166534">• Gaz Mol Sayısı Değişimi:</text>\n  <text x="38" y="112" font-size="10" fill="#334155">N2(g) + 3H2(g) -&gt; 2NH3(g)</text>\n  <text x="38" y="126" font-size="10" fill="#475569">(Sabit V ve T\'de basınç azalması;</text>\n  <text x="38" y="140" font-size="10" fill="#475569">sabit P ve T\'de hacim azalması)</text>\n  <text x="30" y="164" font-size="10.5" font-weight="bold" fill="#166534">• Renk Değişimi:</text>\n  <text x="38" y="180" font-size="10" fill="#334155">H2(g) + Br2(g) -&gt; 2HBr(g)</text>\n  <text x="38" y="194" font-size="10" fill="#475569">(Kızıl kahve rengin açılması)</text>\n\n  <rect x="245" y="48" width="210" height="192" rx="8" fill="#ede9fe" stroke="#7c3aed" stroke-width="1.8"/>\n  <text x="350" y="72" text-anchor="middle" font-size="12" font-weight="bold" fill="#5b21b6">2. İletkenlik ve pH Değişimi</text>\n  <text x="255" y="96" font-size="10.5" font-weight="bold" fill="#6d28d9">• Elektriksel İletkenlik:</text>\n  <text x="263" y="112" font-size="10" fill="#334155">Ag+(suda) + Cl-(suda) -&gt; AgCl(k)</text>\n  <text x="263" y="126" font-size="10" fill="#475569">(İyon derişimi ve iletkenlik azalır)</text>\n  <text x="255" y="156" font-size="10.5" font-weight="bold" fill="#6d28d9">• pH Değişimi:</text>\n  <text x="263" y="172" font-size="10" fill="#334155">Mg(k) + 2H+(suda) -&gt; Mg2+(suda) + H2(g)</text>\n  <text x="263" y="186" font-size="10" fill="#475569">(H+ azaldıkça asitlik azalır,</text>\n  <text x="263" y="200" font-size="10" fill="#475569">pH değeri zamanla artar)</text>\n\n  <rect x="470" y="48" width="210" height="192" rx="8" fill="#fce7f3" stroke="#db2777" stroke-width="1.8"/>\n  <text x="575" y="72" text-anchor="middle" font-size="12" font-weight="bold" fill="#9d174d">3. Tepken Cinsi Hız Sırası</text>\n  <text x="480" y="96" font-size="10.5" font-weight="bold" fill="#be185d">1. En Hızlı (Zıt Yüklü İyon):</text>\n  <text x="488" y="112" font-size="10" fill="#334155">Pb2+(suda) + 2I-(suda) -&gt; PbI2(k)</text>\n  <text x="480" y="138" font-size="10.5" font-weight="bold" fill="#be185d">2. Orta Hızlı (Aynı Yüklü İyon):</text>\n  <text x="488" y="154" font-size="10" fill="#334155">Fe2+ + Ce4+ -&gt; Fe3+ + Ce3+</text>\n  <text x="480" y="180" font-size="10.5" font-weight="bold" fill="#be185d">3. En Yavaş (Çok Bağlı Molekül):</text>\n  <text x="488" y="196" font-size="10" fill="#334155">C3H8(g) + 5O2(g) -&gt; 3CO2 + 4H2O</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
